tool_args.command:
python3 -c "
import json
# Check if SciERC/DocRED constraints are rectangular (σ(r) = dom(r) × range(r))
# by loading the ontology files
import os
base = '/root/schema_semantic_constrained_ie'
for ds in ['scierc', 'docred']:
    schema_path = os.path.join(base, 'ontology', f'{ds}_ontology.json')
    if os.path.exists(schema_path):
        with open(schema_path) as f:
            schema = json.load(f)
        print(f'=== {ds} ===')
        print(f'Keys: {list(schema.keys())[:10]}')
        # Show first 2 relations
        if 'relations' in schema:
            for r in list(schema['relations'].items())[:2]:
                print(f'  {r}')
        elif 'constraints' in schema:
            for r in list(schema['constraints'].items())[:2]:
                print(f'  {r}')
        else:
            print(json.dumps(schema, indent=2)[:500])
    else:
        print(f'{schema_path} not found')
"
